import{_ as n,o as s,c as a,a3 as i,j as e,a as t}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/schueler/einstellungen-automatische-prozesse-1.png",f=JSON.parse('{"title":"Automatische Prüfprozesse manuell starten","description":"","frontmatter":{"title":"Automatische Prüfprozesse manuell starten","source_pageid":371,"source_revision":4789},"headers":[],"relativePath":"schild3/schueler/automatische-prozesse-ausfuehren-verwaltung-werkzeuge.md","filePath":"schild3/schueler/automatische-prozesse-ausfuehren-verwaltung-werkzeuge.md"}'),o={name:"schild3/schueler/automatische-prozesse-ausfuehren-verwaltung-werkzeuge.md"};function u(c,r,h,d,m,p){return s(),a("div",null,[...r[0]||(r[0]=[i('<h1 id="automatische-prufprozesse-manuell-starten" tabindex="-1">Automatische Prüfprozesse manuell starten <a class="header-anchor" href="#automatische-prufprozesse-manuell-starten" aria-label="Permalink to &quot;Automatische Prüfprozesse manuell starten&quot;">​</a></h1><p>Starten Sie die sonst beim Programmstart regelmäßig ausgeführten Prüfungen bei Bedarf manuell. Dabei werden unter anderem fehlende Lernabschnitte und Änderungen altersbezogener Merkmale geprüft.</p><p><a href="/bilder/schueler/einstellungen-automatische-prozesse-1.png"><img src="'+l+'" alt="Automatische Prozesse manuelle anstoßen." loading="lazy"></a></p><p><em>Automatische Prozesse manuelle anstoßen.</em></p><p>Diese Prozesse werden einmal pro Woche von SchILD-NRW beim Start automatisch angestoßen.</p><p>Sie können diese aber auch manuell mit diesem Menüpunkt ablaufen lassen. Diese ist über <em>Verwaltung ➜ Werkzeuge ➜ Automatische Prozesse ausführen</em> zu erreichen. Der Prozess wird mit <strong>Automatische Prozesse starten</strong> gestartet.</p><p>Prüfungen, die durchgeführt werden, sind zum Beispiel:</p><ul><li>Ob alle Schüler einen Lernabschnitt im aktuellen Halbjahr haben. Sollte z.B. bei einigen Schülern, die aus dem Karteikasten &quot;Neuaufnahme&quot; aktiviert wurden, noch nie der Reiter &quot;Akt. Halbjahr&quot; angeklickt worden sein, so wird dies an dieser Stelle nachgeholt.</li><li>Sind Schülerinnen oder Schüler seit der letzten Prüfung volljährig geworden?</li><li>An weiterführenden Schulen - außer an BKs - wird das Erreichen des Endes der Schulpflicht geprüft.</li></ul>',8),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),t("Achtung")]),e("p",null,"Ein falsches Systemdatum von Windows kann zu unerwünschten Ergebnissen führen!")],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Automatische_Prozesse_ausf%C3%BChren_(Verwaltung_Werkzeuge)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),t(" · Quellrevision 4789.")],-1)])])}const z=n(o,[["render",u]]);export{f as __pageData,z as default};
